<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { api,type Data } from '../api/client';import { useRequest } from '../composables/useRequest';import { confirmAction } from '../lib/ui'
import PageHeader from '../components/PageHeader.vue';import EmptyState from '../components/EmptyState.vue';import Icon from '../components/Icon.vue'
const {run,busy,error}=useRequest();const bases=ref<Data[]>([]),notes=ref<Data[]>([]),selected=ref<Data|null>(null),detail=ref<Data|null>(null),results=ref<Data[]>([]),query=ref(''),tab=ref<'search'|'sources'|'points'|'notes'>('search'),points=ref<Data[]>([])
const dialog=ref(false),editing=ref<Data|null>(null),form=reactive({name:'',description:''}),noteDialog=ref(false),noteForm=reactive({title:'',content:''});const activeName=computed(()=>selected.value?.name||'选择知识库')
async function refresh(){const[k,n]=await Promise.all([api.get<Data[]>('/knowledge-bases'),api.get<Data[]>('/notes')]);bases.value=k;notes.value=n;if(selected.value){const f=k.find(x=>x.id===selected.value?.id);if(f){selected.value=f;await loadDetail()}}else if(k.length)await choose(k[0])}
async function choose(item:Data){selected.value=item;results.value=[];await loadDetail()}async function loadDetail(){if(!selected.value)return;detail.value=await api.get(`/knowledge-bases/${selected.value.id}`);points.value=await api.get(`/knowledge-points?knowledge_base_id=${encodeURIComponent(selected.value.id)}`)}
async function search(){if(!query.value.trim())return;await run(async()=>{const data=await api.post('/knowledge/search',{question:query.value.trim(),knowledge_base_id:selected.value?.id||null});results.value=data.citations||[]},'本地检索完成')}
function openCreate(){editing.value=null;form.name='';form.description='';dialog.value=true}function openEdit(){if(!selected.value)return;editing.value=selected.value;form.name=selected.value.name;form.description=selected.value.description||'';dialog.value=true}
async function saveBase(){await run(async()=>{if(editing.value)await api.patch(`/knowledge-bases/${editing.value.id}`,form);else await api.post('/knowledge-bases',form);dialog.value=false;await refresh()},'知识库已保存')}async function remove(){if(!selected.value||!await confirmAction(`删除知识库「${selected.value.name}」？`))return;await run(async()=>{await api.delete(`/knowledge-bases/${selected.value!.id}`);selected.value=null;detail.value=null;await refresh()},'知识库已删除')}
async function createNote(){await run(async()=>{await api.post('/notes',noteForm);noteForm.title='';noteForm.content='';noteDialog.value=false;notes.value=await api.get('/notes')},'笔记已保存')}async function removeNote(item:Data){if(!await confirmAction(`删除笔记「${item.title}」？`))return;await run(async()=>{await api.delete(`/notes/${item.id}`);notes.value=await api.get('/notes')},'笔记已删除')}onMounted(()=>run(refresh))
</script>
<template><section class="page knowledge-page"><PageHeader title="多专业知识库" eyebrow="跨学科学习 · 本地检索 · 原文可查" description="覆盖计算机、数学、物理、电子、经管、医学、生物、法学、语言、教育与心理等专业"><RouterLink class="secondary" to="/documents"><Icon name="upload" :size="17"/>管理资料</RouterLink><button class="primary" @click="openCreate"><Icon name="plus" :size="17"/>新建知识库</button></PageHeader><div v-if="error" class="error-banner">{{error}}</div><div class="knowledge-metrics"><div><span>知识专题</span><strong>{{bases.length}}</strong><small>按领域组织内容</small></div><div><span>知识文档</span><strong>{{bases.reduce((n,x)=>n+Number(x.document_count||0),0)}}</strong><small>均可查看原文</small></div><div><span>可检索分块</span><strong>{{bases.reduce((n,x)=>n+Number(x.chunk_count||0),0)}}</strong><small>本地语义与关键词检索</small></div><div><span>学习笔记</span><strong>{{notes.length}}</strong><small>记录自己的理解</small></div></div><div class="knowledge-layout"><aside class="panel kb-sidebar"><div class="panel-head"><div><h2>知识专题</h2><p>选择一个专业领域</p></div><button class="icon-button soft" aria-label="新建知识库" @click="openCreate"><Icon name="plus"/></button></div><button v-for="base in bases" :key="base.id" class="kb-item" :aria-pressed="selected?.id===base.id" :class="{selected:selected?.id===base.id}" @click="choose(base)"><span class="kb-orb"><Icon name="layers" :size="16"/></span><span><strong>{{base.name}}</strong><small>{{base.document_count||0}} 份资料 · {{base.chunk_count||0}} 个分块</small></span><Icon name="arrow" :size="14"/></button></aside><main v-if="selected" class="knowledge-main"><section class="knowledge-hero"><div><h2>{{activeName}}</h2><p>{{selected.description}}</p><div class="meta-row"><span>{{selected.document_count||0}} 份资料</span><span>{{selected.chunk_count||0}} 个分块</span></div></div><div class="button-row"><button class="secondary small" @click="openEdit">编辑</button><button class="danger small" @click="remove">删除</button></div></section><nav class="knowledge-tabs" aria-label="知识库内容"><button v-for="item in [['search','本地检索','search'],['sources','专题资料','file'],['points','知识点','layers'],['notes','学习笔记','edit']]" :key="item[0]" :class="{active:tab===item[0]}" :aria-pressed="tab===item[0]" @click="tab=item[0] as any"><Icon :name="item[2]" :size="16"/>{{item[1]}}</button></nav><section v-if="tab==='search'" class="panel rag-panel"><div class="panel-head"><div><h2>检索原文</h2><p>完全本地运行，直接返回相关知识片段，不生成、不改写</p></div><span class="pill success">本地检索</span></div><form class="rag-form" @submit.prevent="search"><textarea aria-label="检索原文关键词" v-model="query" maxlength="4000" placeholder="例如：什么是进程与线程？如何理解需求弹性？心输出量如何计算？"></textarea><div class="rag-foot"><span class="muted">检索范围：{{activeName}}</span><button class="primary" :disabled="busy||!query.trim()"><Icon name="search" :size="16"/>搜索知识</button></div></form><div v-if="results.length" class="local-results"><article v-for="(item,index) in results" :key="item.chunk_id"><span>{{Number(index)+1}}</span><div><strong>{{item.name}} · 第 {{item.page||1}} 页</strong><p>{{item.content}}</p><small>相关度 {{Math.round(Number(item.score)*100)}}%</small></div></article></div><EmptyState v-else title="输入关键词开始检索" description="搜索结果直接来自知识库原文，可继续前往专题资料查看完整文档。" icon="search"/></section><section v-else-if="tab==='sources'" class="panel"><div class="panel-head"><div><h2>专题资料</h2><p>已归档到当前专题的原始内容</p></div></div><div v-for="doc in detail?.documents||[]" :key="doc.id" class="source-row"><span class="file-badge">TXT</span><div class="grow"><strong>{{doc.original_name}}</strong><small>{{doc.page_count||1}} 页 · {{doc.index_mode==='semantic'?'语义检索':'关键词检索'}}</small></div><RouterLink class="secondary small" :to="{path:'/documents',query:{id:doc.id}}">阅读原文<Icon name="arrow" :size="15"/></RouterLink></div></section><section v-else-if="tab==='points'" class="panel"><div class="panel-head"><h2>知识点目录</h2><span class="count-badge">{{points.length}}</span></div><div class="knowledge-point-grid"><article v-for="point in points" :key="point.id"><span class="point-index">KP</span><h3>{{point.title}}</h3><p>{{point.description}}</p></article></div><EmptyState v-if="!points.length" title="知识点随资料持续完善" icon="layers"/></section><section v-else class="panel"><div class="panel-head"><div><h2>学习笔记</h2><p>记录自己的理解与疑问</p></div><button class="secondary small" @click="noteDialog=true">新建笔记</button></div><div class="notes-grid"><article v-for="note in notes" :key="note.id" class="note-card"><button class="icon-button danger-text" @click="removeNote(note)"><Icon name="trash" :size="14"/></button><h3>{{note.title}}</h3><p>{{note.content}}</p></article></div></section></main><section v-else class="panel knowledge-empty"><EmptyState title="选择一个专业知识专题" icon="layers"/></section></div><ElDialog v-model="dialog" :title="editing?'编辑知识库':'新建知识库'" width="520px"><form class="stack-form" @submit.prevent="saveBase"><label>名称<input v-model.trim="form.name" required/></label><label>描述<textarea v-model="form.description" rows="4"></textarea></label><div class="dialog-actions"><button type="button" class="secondary" @click="dialog=false">取消</button><button class="primary">保存</button></div></form></ElDialog><ElDialog v-model="noteDialog" title="新建笔记" width="560px"><form class="stack-form" @submit.prevent="createNote"><label>标题<input v-model.trim="noteForm.title" required/></label><label>内容<textarea v-model.trim="noteForm.content" required rows="8"></textarea></label><div class="dialog-actions"><button type="button" class="secondary" @click="noteDialog=false">取消</button><button class="primary">保存</button></div></form></ElDialog></section></template>